USE toolshare;

-- 42 Complete Tools with Dual Pricing, Categorized Locations & Local Relative Image Assets
ON DUPLICATE KEY UPDATE tool_name=VALUES(tool_name), category=VALUES(category), description=VALUES(description), tool_condition=VALUES(tool_condition), location=VALUES(location), hourly_rate=VALUES(hourly_rate), daily_rate=VALUES(daily_rate), image_url=VALUES(image_url), availability_status=VALUES(availability_status);
